import type { CSSProperties, ReactNode } from "react";

/** Widths generated by scripts/optimise-images.py for each photo. */
const WIDTHS: Record<string, number[]> = {
  portrait: [480, 800],
  "portrait-hero": [480, 800, 1200],
  "company-van-damme": [480, 960],
  "company-geiss": [480, 960],
  "company-sesay": [480, 960],
};
const DEFAULT_WIDTHS = [480, 960, 1440];

export function srcSet(name: string) {
  const widths = WIDTHS[name] ?? DEFAULT_WIDTHS;
  return {
    src: `/media/${name}-${widths[widths.length - 1]}.webp`,
    srcSet: widths.map((w) => `/media/${name}-${w}.webp ${w}w`).join(", "),
  };
}

type PhotoProps = {
  name: string;
  alt: string;
  sizes: string;
  shape?: "tall" | "wide" | "square";
  parallax?: number;
  priority?: boolean;
  className?: string;
  delay?: number;
};

/** A framed photo that wipes open on reveal and drifts gently on scroll. */
export function Photo({ name, alt, sizes, shape = "tall", parallax = 0.08, priority, className, delay = 0 }: PhotoProps) {
  const { src, srcSet: set } = srcSet(name);
  return (
    <div
      className={`frame frame--${shape} ${className ?? ""}`}
      data-reveal="image"
      style={{ "--d": `${delay}s` } as CSSProperties}
    >
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={src}
        srcSet={set}
        sizes={sizes}
        alt={alt}
        loading={priority ? "eager" : "lazy"}
        decoding="async"
        data-parallax={parallax}
      />
    </div>
  );
}

export function Kicker({ children }: { children: ReactNode }) {
  return (
    <p className="kicker label" data-reveal="fade">
      {children}
    </p>
  );
}

export function Arrow() {
  return (
    <svg className="btn__arrow" viewBox="0 0 24 24" aria-hidden="true">
      <path d="M3 12h17M14 6l6 6-6 6" fill="none" stroke="currentColor" strokeWidth="1.2" />
    </svg>
  );
}

export function Monogram({ className = "monogram" }: { className?: string }) {
  return (
    // The Spire: the I rises through the M like a tower, with a blue tip and a horizon line beneath.
    <svg className={className} viewBox="0 0 200 200" aria-hidden="true" fill="none">
      <g className="monogram__mi" strokeWidth="7" strokeLinecap="square">
        <path d="M52 158V62l48 62 48-62v96" />
        <path d="M100 158V40" />
        <path d="M40 158h24M136 158h24M88 158h24" />
      </g>
      <path d="M100 40V18" stroke="currentColor" strokeWidth="4.5" />
      <path d="M28 176h144" stroke="currentColor" strokeWidth="3" />
    </svg>
  );
}

/** Splits a delay sequence for staggered reveals. */
export const d = (i: number, step = 0.12, base = 0) => ({ "--d": `${base + i * step}s` }) as CSSProperties;
